"""Final ZIP tarayıcı kanıtı: kurumsal motor panelden uçtan uca — istek öner → kohortu dondur → uzlaştır → detay; Hedefler'de birim kararı (karşı teklif); Dikkat'te merkezi karar (kabul → projeksiyon); Aksiyonlar'da dağıtım kabul + yerel aksiyon taslağı; Control Tower alanları."""
import re, json, requests, time; CODE=f'MA-CES-{int(time.time())%100000}'
from playwright.sync_api import sync_playwright
BASE='http://localhost:8788'; out=[]
def ok(n,c,note=''): out.append({'adim':n,'sonuc':'GEÇTİ' if c else 'KALDI','not':note}); print('OK  ' if c else 'FAIL', n, note[:140]); assert c, n
s=requests.Session(); s.post(BASE+'/api/auth/login', json={'email':'admin@hpw.bos.test','password':'Bos-Admin-2026'}); tid=[x for x in s.get(BASE+'/api/platform/tenants').json() if x['code'].startswith('ALFA')][0]['id']; s.post(BASE+'/api/auth/switch-tenant', json={'tenantId':tid})
cycles=s.get(f'{BASE}/api/t/{tid}/cycles').json(); c25=[c for c in cycles if c['code']=='2025-ANA'][0]; units=s.get(f'{BASE}/api/t/{tid}/cycles/{c25["id"]}/units').json(); konak=[u for u in units if u['code']=='KONAK'][0]
with sync_playwright() as p:
    b=p.chromium.launch(); ctx=b.new_context(viewport={'width':1440,'height':1100}); pg=ctx.new_page(); pg.set_default_timeout(20000)
    pg.goto(BASE+'/#/giris'); pg.fill('#email','admin@hpw.bos.test'); pg.fill('#password','Bos-Admin-2026'); pg.get_by_role('button',name='Giriş yap').click(); pg.wait_for_url(re.compile('#/t/|#/platform')); pg.goto(f'{BASE}/#/platform'); pg.wait_for_timeout(800)
    pg.locator('table').first.locator('tbody tr').filter(has_text='ALFA').get_by_role('button',name='Aç').click(); pg.wait_for_url(re.compile('#/t/')); pg.wait_for_timeout(1500)
    ok('1 Genel bakış: kurumsal planlama paneli', pg.get_by_text('Kurumsal planlama').count()==1)
    pg.select_option('#amb-cycle', c25['id']); pg.fill('#amb-item','CES-04'); pg.fill('#amb-val','85'); pg.fill('#amb-why','2026 kurumsal güven hedefi'); pg.get_by_role('button',name='İstek öner').click(); pg.wait_for_timeout(1500); ok('2 istek önerildi (taslak)', pg.get_by_text('Kurumsal istek kaydedildi').count()==1)
    pg.get_by_role('button', name='kohortu dondur').first.click(); pg.wait_for_timeout(1500); ok('3 kohort donduruldu', pg.get_by_text('Kohort donduruldu').count()==1)
    pg.get_by_role('button', name='uzlaştır').first.click(); pg.wait_for_timeout(1500); ok('4 uzlaştırma hesaplandı (yerel hedef değişmeden)', pg.get_by_text('Uzlaştırma hesaplandı').count()==1)
    pg.get_by_role('button', name='aç').first.click(); pg.wait_for_timeout(1500); txt=pg.locator('main').inner_text(); ok('5 istek detayı: projeksiyon, kurumsal fark, kohort kırılımı', 'KURUMSAL FARK' in txt.upper().replace('İ','I') and 'KIRILIM' in txt.upper().replace('İ','I') and 'PROJEKS' in txt.upper()); pg.screenshot(path='/tmp/tur-out/kurumsal-planlama.png')
    amb=s.get(f'{BASE}/api/t/{tid}/corporate/ambitions').json()['ambitions'][0]; before=s.get(f'{BASE}/api/t/{tid}/cycles/{c25["id"]}/units/{konak["id"]}/targets').json()
    pg.goto(f'{BASE}/#/t/{tid}/hedefler?unit={konak["id"]}&cycle={c25["id"]}'); pg.wait_for_timeout(2500); ok('6 Hedefler: kurumsal uzlaştırma bölümü (bu birim)', pg.get_by_text('Kurumsal uzlaştırma').count()==1)
    pg.on('dialog', lambda d: d.accept('yerel veri 80 ötesini desteklemiyor' if 'gerekçe' in d.message.lower() else ('80' if 'değeri' in d.message else 'tamam'))); pg.get_by_role('button', name='karşı teklif').first.click(); pg.wait_for_timeout(1500); ok('7 birim karşı teklif verdi', 'COUNTERPROPOSAL' in pg.locator('main').inner_text().upper(), pg.locator('main').inner_text().upper()[pg.locator('main').inner_text().upper().find('KURUMSAL UZLA'):][:200])
    after=s.get(f'{BASE}/api/t/{tid}/cycles/{c25["id"]}/units/{konak["id"]}/targets').json(); ok('7b yerel hedefler değişmedi (kota yok)', [t['approved_target'] for t in after]==[t['approved_target'] for t in before])
    pg.goto(f'{BASE}/#/t/{tid}/dikkat'); pg.wait_for_timeout(1500); row=pg.locator('table').filter(has_text='Karşı teklif').locator('tbody tr').filter(has_text='80 ötesini desteklemiyor').filter(has_text='open').last; row.get_by_role('button', name='karar ver').click(); pg.wait_for_timeout(1500)
    det=s.get(f'{BASE}/api/t/{tid}/corporate/ambitions/{amb["id"]}').json(); kon=[c for c in det['cohort'] if c['unit_id']==konak['id']][0]; ok('8 merkezi karar (kabul) projeksiyonu karşı teklife çekti', kon['reconciliation']=='counterproposal_accepted' and float(kon['projection_value'])==80.0, json.dumps({'rec':kon['reconciliation'],'proj':kon['projection_value']}))
    ma=s.post(f'{BASE}/api/t/{tid}/corporate/master-actions', json={'ambitionId':amb['id'],'code':CODE,'title':'Adalet konuşmaları programı','cadence':'monthly'}).json(); dp=s.post(f'{BASE}/api/t/{tid}/corporate/master-actions/{ma["id"]}/deploy', json={'unitCodes':['KONAK','BORNOVA']}).json(); ok('9 ana aksiyon yayımlandı ve 2 birime dağıtıldı (API, İK yöneticisi)', dp.get('deployed')==2)
    pg.goto(f'{BASE}/#/t/{tid}/aksiyonlar?unit={konak["id"]}&cycle={c25["id"]}'); pg.wait_for_timeout(2500); ok('10 Aksiyonlar: dağıtım satırı bekliyor', pg.get_by_text('Ana aksiyon dağıtımları').count()==1 and pg.get_by_role('button', name='kabul et').count()>=1)
    pg.locator('table').filter(has_text='Ana aksiyon').locator('tbody tr').filter(has_text=CODE).get_by_role('button', name='kabul et').click(); pg.wait_for_timeout(3500); deps=s.get(f'{BASE}/api/t/{tid}/corporate/deployments?unitId={konak["id"]}').json(); d0=[d for d in deps if d['code']==CODE][0]; ok('11 dağıtım kabul edildi ve ana aksiyondan yerel aksiyon taslağı bağlandı', d0['local_response']=='accepted' and d0['local_action_id'] is not None, json.dumps({'resp':d0['local_response'],'act':d0['local_action_title']})); pg.screenshot(path='/tmp/tur-out/dagitim.png')
    ct=s.get(f'{BASE}/api/t/{tid}/corporate/control-tower').json(); ok('12 Control Tower: istek/projeksiyon/fark, ana aksiyon bazında dağıtım, tazelik, kuyruk yaşı', ct['ambitionDetail'][0]['contributionProjection'] is not None and ct['byMasterAction'] and 'freshness' in ct and 'oldestDays' in ct['queue'])
    b.close()
json.dump(out, open('/tmp/tur-out/ui-kurumsal-v269-sonuc.json','w',encoding='utf-8'), ensure_ascii=False, indent=1); print(f'{sum(1 for o in out if o["sonuc"]=="GEÇTİ")}/{len(out)}')
